function calciumTransient(p){
  const multi=p.useMultiCa,end=5*(multi?Math.max(p.caTauSlow,p.caTauFast):p.caTau),n=420,tMin=.001;
  const x=[tMin,tMin,tMin],rest=p.caRestActual*1e6,scale=1;
  const fastAmp=multi?scale*p.caAmplGlobal*(1-p.caFracSlow):scale*p.caAmpl;
  const slowAmp=multi?scale*p.caAmplGlobal*p.caFracSlow:0,localAmp=multi?scale*p.caAmplLocal:0;
  const total=[rest,rest,rest+(fastAmp+slowAmp+localAmp)*1e6],global=[0,0,(fastAmp+slowAmp)*1e6],local=[0,0,localAmp*1e6];
  for(let i=1;i<=n;i++){
    const t=end*Math.pow(i/n,3),fast=fastAmp*Math.exp(-t/(multi?p.caTauFast:p.caTau)),slow=multi?slowAmp*Math.exp(-t/p.caTauSlow):0,localValue=multi?localAmp*Math.exp(-t/p.caTauLocal):0;
    x.push(Math.max(t*1e3,tMin));total.push((p.caRestActual+fast+slow+localValue)*1e6);global.push((fast+slow)*1e6);local.push(localValue*1e6);
  }
  return {x,total,global,local,multi};
}
