  for(let i=0;i<=4;i++){const yy=m.t+i*(H-m.t-m.b)/4,lv=lb-i*(lb-la)/4,rv=rb-i*(rb-ra)/4;svg.append(svgEl("line",{x1:m.l,y1:yy,x2:W-m.r,y2:yy,class:"grid-line"}));svg.append(svgEl("text",{x:m.l-7,y:yy+4,"text-anchor":"end",class:"axis-label axis-left"},tick(lv)));svg.append(svgEl("text",{x:W-m.r+7,y:yy+4,"text-anchor":"start",class:"axis-label axis-right"},tick(rv)));const tv=ta+i*(tb-ta)/4,xv=logX?10**tv:tv,xx=m.l+i*(W-m.l-m.r)/4;svg.append(svgEl("text",{x:xx,y:H-17,"text-anchor":"middle",class:"axis-label"},tick(xv)))}
